            % plot(eucdn_sqr_err_pdot)
            % plot(pdiscnt_violation_index) 
            % geoplot(gfinish(:,1),gfinish(:,2),'o'); hold on; geoplot(gmrkd(:,1),gmrkd(:,2),'x'); hold off % <-- 
        end 
        function [marker_costs,end_point_cost,pdiscnt_cost,... % get_costs_ekfodo_S7b
                odo_cost,vel_odo_cost,ekf_odo_cost,ekf_marker_costs] = get_costs_ekfodo_S7b(varargin) 
            if nargin==5 
                [obj,odo_gen,p_gen,odo_data,noindices] = varargin{:}; 
                del_y_ekf = zeros(length(odo_gen),4); 
            elseif nargin==6 
                [obj,odo_gen,p_gen,odo_data,del_y_ekf,noindices] = varargin{:}; 
            end 
            Div_odo = 5e3; 
            % v-- here 
            Q = diag([2e7,2e7,1e-3]); % 1km error x-y plane & z axis produces ~1e3 
            end_Wt = [1,10,1,1,1;1,10,1,2,1]; % marker_costs,end_point_cost,straightning_cost,odo_cost,vel_odo_cost 
            eps_end_pt = -0.25*[0.2,0.5]; % put minus sign to DISABLE 
            elevation_allowed = 5; % meters 
            discnt_lmt_sq_dist = 1; % sq meters 
            % 
            final_state = p_gen(:,end); 
            %             straightning_err = [p_gen(1,ceil(noindices/2)),p_gen(2,ceil(noindices/2))] - ...
            %                 [mean([obj.start_gps(1),p_gen(1,end)]),mean([obj.start_gps(2),p_gen(2,end)])]; 
            % %                     straightning_err = [p_gen(1,ceil(noindices/2)),p_gen(2,ceil(noindices/2))] - ...
            % %                         [mean([obj.start_gps(1),obj.end_gps(1)]),mean([obj.start_gps(2),obj.end_gps(2)])]; 
            %             straightning_cost = 0*straightning_err*Q(1:2,1:2)*straightning_err'; 
            elevation_cost = 1e-1*max(elevation_allowed,...
                (final_state(3)-obj.end_gps(3))*Q(3,3)*(final_state(3)-obj.end_gps(3))); 
            gps_dist_cost = 0e0*(final_state(1:2)-obj.end_gps(1:2)')'*Q(1:2,1:2)*(final_state(1:2)-obj.end_gps(1:2)'); 
            end_point_cost = gps_dist_cost + elevation_cost; 
            oerr = (odo_data - odo_data(1)) - odo_gen; 
            odo_cost = 1e-1*sqrt(sum(oerr.^2))/Div_odo; % <-- here 
            voerr = oerr(2:end)-oerr(1:end-1); 
            vel_odo_cost = 0e-3*sqrt(sum(voerr.^2)); 
            y_fulltraj = [transpose(odo_data(1)+odo_gen)/obj.odo_gain_guess,p_gen']; 
            [gstart,gfinish,~,gmrkd] = obj.odo_marker_hit(y_fulltraj); 
            err_res = obj.marker_NW_distance(gstart,gfinish,gmrkd,false); 
            marker_costs = (20/30)*sqrt(sum(err_res.^2)); 
            % delp_gen = p_gen(1:2,2:end) - p_gen(1:2,1:end-1); 
            eucdn_err_pdot = gps2meters(p_gen(1,1:end-1)',p_gen(2,1:end-1)',...
                p_gen(1,2:end)',p_gen(2,2:end)'); % diag(delp_gen'*obj.W_gps_eucldn(1:2,1:2)*delp_gen);
            pdiscnt_violation_index = eucdn_err_pdot>discnt_lmt_sq_dist; 
            pdiscnt_upcost = 2e-3*sum(eucdn_err_pdot(pdiscnt_violation_index)); 
            pdiscnt_dwncost = 1e-2*sum(eucdn_err_pdot(~pdiscnt_violation_index)); 
            pdiscnt_cost = pdiscnt_upcost + pdiscnt_dwncost; 
            % 
            ekf_odo_cost = 5e-1*sqrt(sum(del_y_ekf(:,1).^2))/Div_odo; % <-- here 
            % del_p_mes_mrkr_ekf = del_y_ekf(del_y_ekf(:,2)~=0,2:4); 
            % eucldn_sqre_err_mes_mrkr_ekf = diag(del_p_mes_mrkr_ekf*obj.W_gps_eucldn*del_p_mes_mrkr_ekf'); 
            % ekf_mes_marker_costs = (1e0/30)*sqrt(sum(eucldn_sqre_err_mes_mrkr_ekf)); 
            eucldn_dist_err_all_mrkr = gps2meters(gfinish(:,1),gfinish(:,2),gmrkd(:,1),gmrkd(:,2)); % diag(del_p_all_mrkr*obj.W_gps_eucldn(1:2,1:2)*del_p_all_mrkr'); 
            ekf_all_marker_costs = (1/30)*sum(eucldn_dist_err_all_mrkr); 
            ekf_marker_costs = 0*ekf_all_marker_costs; % <-- here || ekf_mes_marker_costs + 
            % odo_cost = 50*odo_cost; % manual edit 
            % end_point_cost = 50*end_point_cost; 
            if marker_costs<eps_end_pt(1) 
                marker_costs = end_Wt(1,1)*marker_costs; 
                elevation_cost = end_Wt(1,2)*elevation_cost; 
                pdiscnt_cost = end_Wt(1,3)*pdiscnt_cost; 
                odo_cost = end_Wt(1,4)*odo_cost; 
                vel_odo_cost = end_Wt(1,5)*vel_odo_cost; 
            elseif marker_costs<eps_end_pt(2) 
                marker_costs = end_Wt(2,1)*marker_costs; 
                elevation_cost = end_Wt(2,2)*elevation_cost; 
                pdiscnt_cost = end_Wt(2,3)*pdiscnt_cost; 
                odo_cost = end_Wt(2,4)*odo_cost; 
                vel_odo_cost = end_Wt(2,5)*vel_odo_cost; 
            end 
            % Analysis 
            % plot(eucdn_sqr_err_pdot)
            % plot(pdiscnt_violation_index) 
            % geoplot(gfinish(:,1),gfinish(:,2),'o'); hold on; geoplot(gmrkd(:,1),gmrkd(:,2),'x'); hold off % <-- 
        end 
        % --> system dynamics portions  
        function [v, v_dot] = get_velocity_trajectory(varargin) % gravity removed acceleration (v_dot) 
            disp('Velovity dynamics using IMU data --> v_dot = C_q a_IMU - g ! ') 
            disp('Assuming: we know the orientation data! ') 
            obj = varargin{1}; 
            if nargin>1 
                indices = varargin{2}; 
            else 
                indices = obj.start_index:floor(obj.delta_index/20):obj.end_index; 
            end 
            g_all = obj.get_gravity_at_fraction_or_index(indices); 
            C_q = @(q) quat2rotm(q'); 
            noindices = length(indices); 
            v_dot = zeros(3,noindices); 
            v = zeros(3,noindices); 
            for i=2:noindices 
                indx = indices(i-1); 
                new_q = obj.best_quaternion_orientation_trajectory(:,indx); 
                v_dot(:,i) = C_q(new_q)*g_all(:,i-1) - [0;0;obj.earth_gravity]; 
                dT = obj.downsampling*(indices(i)-indices(i-1))/obj.sampling_frequency; 
                v(:,i) = v(:,i-1) + dT*v_dot(:,i-1); 
            end 
        end 
        function d_gen = get_distance_trajectory(varargin) % generate distance 
            disp('Velovity dynamics using IMU data --> v_dot = C_q a_IMU - g ! ') 
            disp('Assuming: we know the orientation data! ') 
            obj = varargin{1}; 
            if nargin>1 
                indices = varargin{2}; 
            else 
                indices = obj.start_index:floor(obj.delta_index/20):obj.end_index; 
            end 
            noindices = length(indices); 
            v = obj.get_velocity_trajectory(indices); 
            d_gen = zeros(3,noindices); 
            for i=1:noindices 
                if i>1 
                    dT = obj.downsampling*(indices(i)-indices(i-1))/obj.sampling_frequency; 
                    d_gen(:,i) = d_gen(:,i-1) + dT*v(:,i-1); 
                end 
            end 
        end 
        function [w, new_q] = get_orientation_derivative_trajectory(varargin) % 
            disp('Computation: w = 2 Qinv (q_k+1 - q_k)*fs ')
            obj = varargin{1}; 
            if nargin>1 
                indices = varargin{2}; 
            else 
                indices = obj.start_index:floor(obj.delta_index/20):obj.end_index; 
            end 
            S_q = @(q) [-q(2),-q(3),-q(4);q(1),-q(4),q(3);q(4),q(1),-q(2);-q(3),q(2),q(1)]; 
            noindices = length(indices); 
            w = zeros(3,noindices); 
            for i=2:noindices 
                prev_indx = indices(i-1); 
                indx = indices(i); 
                q = obj.best_quaternion_orientation_trajectory(:,prev_indx); 
                new_q = obj.best_quaternion_orientation_trajectory(:,indx); 
                dT = obj.downsampling*(indices(i)-indices(i-1))/obj.sampling_frequency; 
                q_dot = (new_q-q)/dT; 
                w(:,i) = 2*S_q(new_q)\q_dot; 
            end 
        end 
        function [q, q_dot] = get_orientation_trajectory_from_imu(varargin) 
            disp('Computation: q_dot = 0.5 S_w q ') 
            obj = varargin{1}; 
            if nargin>1 
                indices = varargin{2}; 
            else 
                indices = obj.start_index:floor(obj.delta_index/20):obj.end_index; 
            end 
            if nargin>2 
                gyro_gain_scl = varargin{3}; 
            else 
                gyro_gain_scl = 0.2274/0.18; 
            end 
            if nargin>3 
                gyro_bias = varargin{4}; 
            else 
                gyro_bias = [0;0;0]; 
            end 
            if nargin>4 
                q_corctn = varargin{5}; 
            else 
                q_corctn = [0;0;0;0]; 
            end 
            sel_data = 1:3; 
            S_w = @(w) [0,-w(1),-w(2),-w(3);w(1),0,w(3),-w(2);w(2),-w(3),0,w(1);w(3),w(2),-w(1),0]; 
            noindices = length(indices); 
            w = diag(gyro_gain_scl*obj.best_gain(4:end))*obj.all_datapoints(sel_data,indices); 
            q_dot = zeros(4,noindices); 
            q = zeros(4,noindices); 
            q(:,1) = obj.best_initial_orientation/norm(obj.best_initial_orientation); % initial condition 
            q(:,1) = (q(:,1)+q_corctn)/norm(q(:,1)+q_corctn); 
            for i=2:noindices 
                dT = obj.downsampling*(indices(i)-indices(i-1))/obj.sampling_frequency; 
                tmp_q = q(:,i-1) + dT*q_dot(:,i-1); 
                q(:,i) = tmp_q/norm(tmp_q); 
                q_dot(:,i) = 0.5*S_w(w(:,i) + gyro_bias)*q(:,i); 
            end 
        end 
        function p_gen = get_gps_trajectory(varargin) % generate gps 
            disp('Velovity dynamics using IMU data --> v_dot = C_q a_IMU - g ! ') 
            disp('Assuming: we know the orientation data! ') 
            obj = varargin{1}; 
            if nargin>1 
                indices = varargin{2}; 
            else 
                indices = obj.start_index:floor(obj.delta_index/20):obj.end_index; 
            end 
            noindices = length(indices); 
            v = obj.get_velocity_trajectory(indices); 
            p_gen = zeros(3,noindices); 
            p_gen(:,1) = obj.start_gps'; 
            G_matrix = @(p) diag([(180/pi)/(obj.north_radius_of_earth + p(3)), ...
                -(180/pi)/((obj.east_radius_of_earth + p(3))*cosd(p(1))), 1]); % Lat Lon Up 
            for i=2:noindices 
                dT = obj.downsampling*(indices(i)-indices(i-1))/obj.sampling_frequency; 
                p_gen(:,i) = p_gen(:,i-1) + dT*G_matrix(p_gen(:,i-1))*v(:,i-1); 
            end 
        end 
        function [odo_dist, gain] = get_odometer_distance(varargin) % generate distance from odometer 
            obj = varargin{1}; 
            if nargin>1 
                indices = varargin{2}; 
            else 
                indices = obj.start_index:floor(obj.delta_index/20):obj.end_index; 
            end 
            % noindices = length(indices); 
            % odo_dist = obj.odo_gain_guess*obj.odometer_max(:,indices); gain = obj.odo_gain_guess; 
            odo_dist = obj.odo_gain_backcalc*obj.odometer_max(:,indices); gain = obj.odo_gain_backcalc; 
        end 
        function [q_dot,q,v_dot,v,p_gen,odo_gen] = get_full_dynamical_trajectory(...
                varargin) % full dynamics with epsilon control 
            obj = varargin{1}; 
            agb_now = varargin{2};  % <-- angle, gains, and biases 
            if nargin>2 % epsilon 
                epsilon = varargin{3}; 
            else 
                epsilon = 1; 
            end 
            if nargin>3 % indices 
                indices = varargin{4}; 
            else 
                indices = obj.start_index:obj.end_index; 
            end 
            if nargin>4 % g and w as input 
                g_all = varargin{5}; 
                w_all = varargin{6}; 
            else 
                g_all = obj.get_gravity_at_fraction_or_index(indices); 
                w_all = diag(obj.best_gain(4:end))*obj.all_datapoints(1:3,indices); 
            end 
            % 
            odo_gain = 1; %agb_now(1); 
            acc_gain_mat = diag(agb_now(2:4)); 
            acc_bias = agb_now(5:7); 
            gyro_gain_mat = diag(agb_now(8:10)); 
            gyro_bias = agb_now(11:13); 
            q0 = obj.best_initial_orientation + agb_now(14:17); 
            v0 = agb_now(18:20); 
            % 
            C_q = @(q) quat2rotm(q'); 
            noindices = length(indices); 
            S_w = @(w) [0,-w(1),-w(2),-w(3);w(1),0,w(3),-w(2);w(2),-w(3),0,w(1);w(3),w(2),-w(1),0]; 
            G_matrix = @(p) diag([(180/pi)/(obj.north_radius_of_earth + p(3)), ...
                -(180/pi)/((obj.east_radius_of_earth + p(3))*cosd(p(1))), 1]); % Lat Lon Up 
            % 
            q_dot = zeros(4,noindices); 
            q = zeros(4,noindices); 
            v_dot = zeros(3,noindices); 
            v = zeros(3,noindices); 
            p_gen = zeros(3,noindices); 
            odo_gen = zeros(1,noindices); 
            q(:,1) = q0; % <-- normalized later 
            v(:,1) = v0; % 
            p_gen(:,1) = obj.start_gps'; 
            % 
            for ix=2:noindices 
                indx = indices(ix-1); 
                old_q = obj.best_quaternion_orientation_trajectory(:,indx); 
                new_q = epsilon*old_q + (1-epsilon)*q(:,ix-1); 
                new_q = new_q/norm(new_q); 
                dT = obj.downsampling*(indices(ix)-indices(ix-1))/obj.sampling_frequency; 
                % 
                q_dot(:,ix) = 0.5*S_w(gyro_gain_mat*w_all(:,ix-1) + gyro_bias)*q(:,ix-1); 
                tmp_q = q(:,ix-1) + dT*q_dot(:,ix-1); 
                q(:,ix) = tmp_q/norm(tmp_q); 
                v_dot(:,ix) = C_q(new_q)*(acc_gain_mat*g_all(:,ix-1) + acc_bias) - [0;0;obj.earth_gravity]; % rotz(z_angle)*
                v(:,ix) = v(:,ix-1) + dT*v_dot(:,ix-1); 
                p_gen(:,ix) = p_gen(:,ix-1) + dT*G_matrix(p_gen(:,ix-1))*v(:,ix-1); 
                odo_gen(:,ix) = odo_gen(:,ix-1) + dT*norm(v(:,ix)); 
            end 
            % odo_gen = odo_gain*dT*cumsum(sqrt(sum(v.*v,1))); 
        end 
        function [q_dot,q,v_dot,v,p_gen,odo_gen,acc_ef] = get_full_dynamical_trajectory_universal(varargin) 
            obj = varargin{1}; 
            agb_now = varargin{2};  % <-- angle, gains, and biases 
            if nargin>2 % epsilon 
                epsilon = varargin{3}; 
            else 
                epsilon = 1; 
            end 
            if nargin>3 % indices 
                indices = varargin{4}; 
            else 
                indices = obj.start_index:obj.end_index; 
            end 
            if nargin>4 % g and w as input 
                g_all = varargin{5}; 
                w_all = varargin{6}; 
                f = varargin{7}; 
                g = varargin{8}; 
                C_nb = varargin{9}; 
            else 
                g_all = obj.get_gravity_at_fraction_or_index(indices); 
                w_all = diag(obj.best_gain(4:end))*obj.all_datapoints(1:3,indices); 
            end 
            % 
            % odo_gain = 1; %agb_now(1); 
            % acc_gain_mat = diag(agb_now(2:4)); 
            acc_bias = agb_now(5:7); 
            % gyro_gain_mat = diag(agb_now(8:10)); 
            gyro_bias = agb_now(11:13); 
            params = agb_now([2:4,8:10]); 
            % q0 = obj.best_initial_orientation + agb_now(14:17); 
            q0 = rotm2quat(rotx(obj.start_gps(2))*roty(obj.start_gps(1))*quat2rotm(obj.best_initial_orientation'))'...
                 + agb_now(14:17); 
            v0 = agb_now(18:20); 
            dT = (indices(2)-indices(1))*obj.downsampling/obj.sampling_frequency; 
            % 
            noindices = length(indices); 
            % 
            q_dot = zeros(4,noindices); 
            q = zeros(4,noindices); 
            v_dot = zeros(3,noindices); 
            v = zeros(3,noindices); 
            p_gen = zeros(3,noindices); 
            odo_gen = zeros(1,noindices); 
            acc_ef = zeros(3,noindices); 
            q(:,1) = q0; % <-- normalized later 
            v(:,1) = v0; % 
            p_gen(:,1) = obj.start_gps'; 
            % 
            for ix=2:noindices 
                indx = indices(ix-1); 
                old_q = obj.best_quaternion_orientation_trajectory(:,indx); 
                new_q = epsilon*old_q + (1-epsilon)*q(:,ix-1); 
                new_q = new_q/norm(new_q); 
                %dT = obj.downsampling*(indices(ix)-indices(ix-1))/obj.sampling_frequency; 
                t = dT*(ix-2); 
                % 
                x = [odo_gen(:,ix-1);p_gen(:,ix-1);new_q;v(:,ix-1);acc_bias;gyro_bias]; 
                u = [g_all(:,ix-1);w_all(:,ix-1)]; 
                x = f(x) + g(t,x,u,params); 
                odo_gen(:,ix) = x(1); p_gen(:,ix) = x(2:4); q(:,ix) = x(5:8); v(:,ix) = x(9:11); 
                % 
                q_dot(:,ix) = (q(:,ix) - q(:,ix-1))/dT; 
                v_dot(:,ix) = (v(:,ix) - v(:,ix-1))/dT; 
                acc_ef(:,ix) = transpose(C_nb(dT*(ix-1),p_gen(:,ix),q(:,ix),v(:,ix)))...
                    *[0;0;obj.earth_gravity]; 
            end 
            % odo_gen = odo_gain*dT*cumsum(sqrt(sum(v.*v,1))); 
        end 
