            acc_gain_mat = diag(agb_now2(2:4)); 
            acc_bias = agb_now2(5:7); 
            gyro_gain_mat = diag(agb_now2(8:10)); 
            gyro_bias = agb_now2(11:13); 
            tmpq = rotm2quat(rotx(obj.start_gps(2))*roty(obj.start_gps(1))*quat2rotm(obj.best_initial_orientation'))'...
                + agb_now2(14:17); 
            q0 = tmpq/norm(tmpq); 
            v0 = agb_now2(18:20); 
            dTprm = agb_now2(21)*obj.downsampling/10; 
            x0 = [obj.odo_gain_guess*obj.odometer_max(obj.start_index);obj.start_gps';q0;v0;[acc_bias;gyro_bias]]; 
