%                 disp(['Iter = ',num2str(i)]) 
%                 disp('Angles = '); disp(quat2eul(x0(5:8)')*180/pi) 
%                 disp(['Cost = ',num2str(mean(diag(del_y*W*del_y')))]) 
%                 disp(['Cost distribution: ', num2str(mean(del_y.^2.*repmat(diag(W)',size(del_y,1),1),1))]) 
%                 disp(' ')
            figure(2) 
            clf 
            obj.show_topt_linear_gps_geoplot_acc_only(y_fulltraj_basecase(:,2:3),mes_markers(:,1:2),...
                non_mes_markers(:,1:2)); 
            [gstart,gfinish,~,gmrkd] = obj.odo_marker_hit(y_fulltraj_basecase); 
