            title('Fully tuned EKF') 
            %saveas(2,[fname,'_gps.png']) 
            %save init_ekf K bs x0 sel_dynamics 
            pause(1) 
            %save ekf_ili_res2 K bs x0 sel_dynamics 

            % Perturbation check 
            stvar_name = {'Odometer gain','Accel-x gain','Accel-y gain','Accel-z gain','Accel-x bias','Accel-y bias','Accel-z bias',...
                'Gyro-x gain','Gyro-y gain','Gyro-z gain','Gyro-x bias','Gyro-y bias','Gyro-z bias','Init Quaternion-0',...
                'Init Quaternion-x','Init Quaternion-y','Init Quaternion-z','Init Velocity-x','Init Velocity-y','Init Velocity-z','Sampling Time',...
                'Q1','Q2','Q3','Q4','Q5','Q6','Q7','Q8','Q9','Q10','Q11','Q12','Q13','Q14','Q15','Q16','Q17',...
                'R1','R2','R3','R4','Re1','Re2','Re3','Re4'}; 
            if obj.auto_mode 
                en_grad_chk = obj.auto_inputs.S7.find_new_grad_en; 
            else 
                en_grad_chk = input('Press `1` to enable graident tuning (press ENTER to skip): '); 
            end 
            % check grad_bounds 
            basecase_agb_now2 = agb_now2; % reset Q and R gains 
            basecase_agb_now2(22:end) = 1; 
            if ~isempty(en_grad_chk) 
                % 
                basecase_agb_now2(to_remove_tuning) = basecase_agb_now2(removed_pairing); 
                new_Q = diag(basecase_agb_now2(22:38))*Q; % Q; % 
                new_R = R; % diag(1./agb_now2(39:42))*R; % 
                new_R_ext = R_ext; % diag(1./agb_now2(43:46))*R_ext; % 
                % [~,~,~,v,p_gen,odo_gen] = obj.get_full_dynamical_trajectory_universal_unknown_sampling(new_agb_now2,...
                %     epsilon,indices,g_all,w_all,f,g,C_nb); 
                new_obj.set_noise_data(new_Q,new_R,new_R_ext); % R.^(-1/1)); 
                vel_scale = basecase_agb_now2(1); 
                acc_gain_mat = diag(basecase_agb_now2(2:4)); 
                acc_bias = basecase_agb_now2(5:7); 
                gyro_gain_mat = diag(basecase_agb_now2(8:10)); 
                gyro_bias = basecase_agb_now2(11:13); 
                tmpq = rotm2quat(rotx(obj.start_gps(2))*roty(obj.start_gps(1))*quat2rotm(obj.best_initial_orientation'))'...
                    + basecase_agb_now2(14:17); 
                q0 = tmpq/norm(tmpq); 
                v0 = basecase_agb_now2(18:20); 
                dTprm = basecase_agb_now2(21)*obj.downsampling/10; 
                x0 = [obj.odo_gain_guess*obj.odometer_max(obj.start_index);obj.start_gps';q0;v0;[acc_bias;gyro_bias]]; 
                K = blkdiag(acc_gain_mat,gyro_gain_mat)*diag(obj.best_gain); 
                bs = repmat([acc_bias;gyro_bias]',N,1); 
                new_obj.set_guess(x0,K,bs); 
                new_obj.set_sys_params(length(x0),N,size(C_ext,1),size(bs,1),dTprm,vel_scale); 
                [x_traj,~,y_fulltraj_basecase] = new_obj.eval_ekf_unknwn_dT_vel_scaled_simple(x0,N); 
                figure(1) 
                clf 
                new_obj.render_output_ekftraj_comparison(); 
                %fname = ['ekf_ili_res2_round_ ',num2str(i)]; 
                %saveas(1,[fname,'.png']); saveas(2,[fname,'_imu.png']) 
    %                 disp(['Iter = ',num2str(i)]) 
    %                 disp('Angles = '); disp(quat2eul(x0(5:8)')*180/pi) 
    %                 disp(['Cost = ',num2str(mean(diag(del_y*W*del_y')))]) 
    %                 disp(['Cost distribution: ', num2str(mean(del_y.^2.*repmat(diag(W)',size(del_y,1),1),1))]) 
    %                 disp(' ')
                figure(2) 
                clf 
                obj.show_topt_linear_gps_geoplot_acc_only(y_fulltraj_basecase(:,2:3),mes_markers(:,1:2),...
                    non_mes_markers(:,1:2)); 
                [gstart,gfinish,~,gmrkd] = obj.odo_marker_hit(y_fulltraj_basecase); 
                obj.marker_projection(gstart,gfinish,gmrkd); 
                title('Partially tuned EKF - reset Q and R ') 
                %saveas(2,[fname,'_gps.png']) 
                %save init_ekf K bs x0 sel_dynamics 
                pause(1) 
                %save ekf_ili_res2 K bs x0 sel_dynamics 
            
                % reset Q and R gradient bounds 
