                final_state_basecase = y_fulltraj_basecase(end,2:4)'; 
                report_perturbation = nan(4,length_of_gain_vector); 
                for i=tuning_param_id 
                    new_agb_now2 = basecase_agb_now2; 
                    % new_Q = Q; new_R = R; new_R_ext = R_ext; 
                    for j=0:number_of_directions 
                        base_j = 3; pwr_j_frac = 0.5; increase_to = 1000; 
                        coeff_j = increase_to/(base_j^(number_of_directions*pwr_j_frac)); 
                        tuning_factor = coeff_j*base_j^j; 
                        new_agb_now2(i) = new_agb_now2(i) + tuning_factor*accleration_factor*grad_bounds(i,i); 
                        new_agb_now2(to_remove_tuning) = new_agb_now2(removed_pairing); 
                        new_Q = diag(new_agb_now2(22:38))*Q; new_R = diag(1./new_agb_now2(39:42))*R; 
                        new_R_ext = diag(1./new_agb_now2(43:46))*R_ext; 
                        % [~,~,~,v,p_gen,odo_gen] = obj.get_full_dynamical_trajectory_universal_unknown_sampling(new_agb_now2,...
                        %     epsilon,indices,g_all,w_all,f,g,C_nb); 
                        new_obj.set_noise_data(new_Q,new_R,new_R_ext); % R.^(-1/1)); 
