                        traj_contri = 0.5*sum(sum((y_fulltraj(:,2:4) - y_fulltraj_basecase(:,2:4)).^2))*2e-2; 
                        report_perturbation(2:4,i) = end_state_contr + traj_contri/3; 
                        if j==number_of_directions || norm(report_perturbation(2:4,i))>20 
