                                ' & traj_contri = ',num2str(traj_contri)]) 
                            disp(['Index j = ',num2str(j),' has tuning_factor = ',num2str(tuning_factor)]) 
                            % sound(sin(2*pi*2000*(0:0.5/8192:1))) % <-- SOUND 
                            pause(0.1) 
                            break 
                        end 
                        if norm(report_perturbation(2:4,i))>1 % approx 1 meter in x-y OR z direction + 'slight' traj deviation 
                            report_perturbation(1,i) = tuning_factor; 
                            figure(1) % <-- testing 
                            geoplot(y_fulltraj(1,2)',y_fulltraj(1,3)','x'); 
