                                ' & traj_contri = ',num2str(traj_contri)]) 
                            disp(['Index j = ',num2str(j),' has tuning_factor = ',num2str(tuning_factor)]) 
                            pause(0.1) 
                            break 
                        end 
                    end 
                end 
                perturbation_magnitude = -0.5*(1-sign(report_perturbation(1,:))) + sqrt(sum(report_perturbation(2:end,:).^2,1)); 
                figure(2) 
