                    report_perturbation(1,isnan(report_perturbation(1,:))) = 1; % number_of_directions; % 
                end 
                grad_bounds = sentvty*diag(abs(report_perturbation(1,:)))*grad_bounds; 
                save to_continue_unkwn_dT_vel_scld_ekfgd agb_now2 start_iter grad_bounds 
            end 
            % disp('Press any key to continue ... ') 
            % pause 
            %             if sum(isnan(report_perturbation(1,:)))>0 
            %                 warning('Too small graidents! ') 
            %                 report_perturbation(1,isnan(report_perturbation(1,:))) = number_of_directions; 
            %             end 

            % main loop 
            if obj.auto_mode 
                rst_agb_now2_ekf_params = []; 
            else 
                rst_agb_now2_ekf_params = input('Press `1` to RESET ekf parameters (press ENTER to skip): '); 
            end 
            if ~isempty(rst_agb_now2_ekf_params) 
