            op_data = gen_vm_at_sampletime(obj,mes_markers,C_swtch_data); 
            % tmp_op = zeros(C_swtch_data(end)+1,3); 
            % tmp_op(C_swtch_data+1,:) = mes_markers; 
            % op_data2 = [obj.odometer_max(obj.start_index:obj.end_index)',tmp_op]; 
            % 
            new_obj.set_sys_params(length(x0),N,size(C_ext,1),size(bs,1),...
                agb_now2(21)*obj.downsampling/10,vel_scale); 
            new_obj.set_system_data(f,g,h,h_ext,x0,f_guess,g_guess,h_guess,...
                h_ext_guess,x0_guess,C_swtch_data); 
            new_obj.set_linearized_and_adjoint_data(A,B,@(x)C,@(x)C_ext); 
            new_obj.set_input_data(transpose([imu_acc;imu_gyr])); 
            %R = [8.15849660302496/N^2,0,0,0;0,4151641837221.92,0,0;0,0,4151641837221.92,0;0,0,0,1647724.67444092]; 
            new_obj.set_noise_data(Q,R,R_ext); % R.^(-1/1)); 
            new_obj.set_output_data(op_data); 
            new_obj.set_guess(x0_guess,K,bs); 
            
            % new_obj.render_output_topttraj_comparison(); 

            % pariring and removal of parameter tuning 
            to_remove_tuning = [22,25,40:42]; 
            removed_pairing = [23,23,39,39,39]; 
            tuning_param_id = 1:length(agb_now2); 
            tuning_param_id(to_remove_tuning) = []; % removed 
            
            factr = 1; 
            new_obj.to_sys_pred_results.sys_data.f = new_obj.sys_data.f_guess; 
            new_obj.to_sys_pred_results.sys_data.g = new_obj.sys_data.g_guess; 
            new_obj.to_sys_pred_results.sys_data.h = new_obj.sys_data.h_guess; 
            new_obj.to_sys_pred_results.sys_data.h_ext = new_obj.sys_data.h_ext_guess; 
            new_obj.to_sys_pred_results.sys_data.x0_guess = new_obj.sys_data.x0_guess; 
            N = new_obj.sys_params.N; 
            new_obj.alpha = 0.3/N^2; 
            guess_sys_data = new_obj.to_sys_pred_results.sys_data; 
            x0_guess = new_obj.sys_data.x0_guess; 
            %     new_obj.eval_ekf(); 
            %     new_obj.eval_ekf(N); 
        
            agb_now2(to_remove_tuning) = agb_now2(removed_pairing); 
            % << conversion from fQtR to regular>> 
            if obj.auto_mode 
                conv_en = []; 
            else 
                conv_en = input('Convert fQtR to regular? (Default is `no`): '); 
            end 
            if ~isempty(conv_en) 
                save unconverted_agb_now2 agb_now2 
                Rodo = 1e17; Rgps = 1e35*[1e-10,1e-12,1e0]; 
                R_fQtR = diag([Rodo,Rgps.*1e12.*[1e-6,1e-6,1e-4]]); % very noisy GPS measurement 
                R_ext_fQtR = diag([Rodo,Rgps.*1e-1.*[1e-6,1e-6,1e-4]]); % very perfect GPS measurement 
                agb_now2(39:42) = diag(R)./diag(diag(1./agb_now2(39:42))*R_fQtR); 
                agb_now2(43:46) = diag(R_ext)./diag(diag(1./agb_now2(43:46))*R_ext_fQtR); 
            end 
            % << ends >>  
            new_Q = diag(agb_now2(22:38))*Q; % Q; % 
            new_R = diag(1./agb_now2(39:42))*R; % R; % 
            % disp('virtual marker special! '); new_Q = Q; new_R = Q(1:4,1:4); 
            new_R_ext = diag(1./agb_now2(43:46))*R_ext; % R_ext; % 
            % [~,~,~,v,p_gen,odo_gen] = obj.get_full_dynamical_trajectory_universal_unknown_sampling(new_agb_now2,...
            %     epsilon,indices,g_all,w_all,f,g,C_nb); 
            new_obj.set_noise_data(new_Q,new_R,new_R_ext); % R.^(-1/1)); 
            vel_scale = agb_now2(1); 
            acc_gain_mat = diag(agb_now2(2:4)); 
            acc_bias = agb_now2(5:7); 
            gyro_gain_mat = diag(agb_now2(8:10)); 
            gyro_bias = agb_now2(11:13); 
            tmpq = rotm2quat(rotx(obj.start_gps(2))*roty(obj.start_gps(1))*quat2rotm(obj.best_initial_orientation'))'...
                + agb_now2(14:17); 
            q0 = tmpq/norm(tmpq); 
            v0 = agb_now2(18:20); 
            dTprm = agb_now2(21)*obj.downsampling/10; 
            x0 = [obj.odo_gain_guess*obj.odometer_max(obj.start_index);obj.start_gps';q0;v0;[acc_bias;gyro_bias]]; 
            K = blkdiag(acc_gain_mat,gyro_gain_mat)*diag(obj.best_gain); 
            bs = repmat([acc_bias;gyro_bias]',N,1); 
            new_obj.set_guess(x0,K,bs); 
            new_obj.set_sys_params(length(x0),N,size(C_ext,1),size(bs,1),dTprm,vel_scale); 
