        % discarding 
        function main_best_orientation_trajectory_new_model_gd(varargin) 

            obj = varargin{1}; 
            if nargin>1 
                skipsample = varargin{2}; 
            else 
                skipsample = 1e4/obj.downsampling; 
            end 
            if nargin>2 
                [lwr,upr] = varargin{2:end}; 
                qsel_indices = floor(linspace(lwr,upr,30)); 
            end 
            if nargin>3 
                [lwr,upr,spcd] = varargin{2:end}; 
                qsel_indices = floor(linspace(lwr,upr,spcd)); 
            end 


            %% Step 1: testingv 
            testf = 50; 
            usegyrodata = 1; 
            % theta = rand*pi; 
            % vec = randn(3,1); 
            % orient_quat = [cos(theta/2);sin(theta/2)*vec/norm(vec)]; 

            % Initialization 
            theta = -2.3*pi/4; 
            vec = [0;0;1]; 
            default_dp_len = obj.get_delta_index; % size(obj.all_datapoints,2); 
            orient_quat = repmat([cos(theta/2);sin(theta/2)*vec/norm(vec)],1,default_dp_len); 
            RotZ_180 = rotz(180); 
            % RotZ_inityaw = rotz(atan2d(obj.start_gps(2)-obj.end_gps(2),...
            %     obj.start_gps(1)-obj.end_gps(1))); % -162 degrees (Don't use this!) 
            
            %% Step 3: Algorithm parameters 
            epsilon = 1e-2; 
            max_steps = 30000; 
            
            %% Step 4: Create gravity and rotation inline function  
            g_all = obj.get_gravity_at_fraction_or_index(obj.start_index:obj.end_index); 
            C_q = @(q) quat2rotm(q'); 
            try 
                load('best_orientation_so_far.mat'); 
                [~] = orient_traj; 
            catch 
                try 
                    qi = obj.best_initial_orientation; 
                    qf = obj.best_final_orientation; 
                    qdiff = qf-qi; 
                    alpha = linspace(0,1,default_dp_len); 
                    orient_traj = repmat(qi,1,default_dp_len) + repmat(alpha,4,1)...
                        .*repmat(qdiff,1,default_dp_len); 
                    orient_traj = orient_traj./repmat(sqrt(sum(orient_traj.^2,1)),4,1); 
                catch 
                    % gains_now = obj.imu_device_obj.get_gains(); 
                    orient_traj = orient_quat; 
                end 
            end 

            %% Step 2: Optimize the orientation quaternion 
            number_of_random_points = 10; 
            number_of_new_orientations = 20; 
            grad_bounds = diag([1e-0*ones(1,4)]); 
            Q = diag([1e0,1e0,1e0]); % weight on the norm of final state 
            length_of_orient_vector = length(grad_bounds); 
            accleration_factor = 0.1; 
            try % qsel_indices was input by user 
                [~] = qsel_indices; 
            catch 
                qsel_indices = obj.start_index:skipsample:obj.end_index; 
            end 
            cost_at_sel = nan(1,length(qsel_indices)); 
            for qsel=qsel_indices 
                for i=1:max_steps 
                    % Sub-step 2a: Choose gradients at uniformly random 
                    random_orient_grads = [zeros(length_of_orient_vector,1), ...
                        2*(0.5-rand(length_of_orient_vector, number_of_new_orientations-1))]; 
    
                    % Sub-step 2b: Find new points along the random
                    % gradients + random points 
                    new_orients = repmat(orient_traj(:,qsel),1,number_of_new_orientations) + accleration_factor*random_orient_grads; 
                    new_orients(:,number_of_new_orientations-number_of_random_points+1:end) ...
                        = 2*(0.5-rand(4,number_of_random_points)); 
    
                    % Sub-step 2c: Evaluate end gps point for all new states 
                    all_costs = inf(1,number_of_new_orientations); 
                    for j=1:number_of_new_orientations 
                        new_q = new_orients(:,j)/norm(new_orients(:,j)); 
                        gravity_orientation_error = ([0;0;obj.earth_gravity] - RotZ_180*C_q(new_q)*g_all(:,qsel)); 
                        all_costs(1,j) = gravity_orientation_error'*Q*gravity_orientation_error; 
                    end 
    
                    % Sub-step 2d: Choose the best and set it as new gain 
                    [best_cost,best_arg] = min(all_costs); 
                    orient_traj(:,qsel) = new_orients(:,best_arg)/norm(new_orients(:,best_arg)); 

                    % Sub-step 2e: Breaking condition 
                    if best_cost<epsilon 
                        break 
                    end 
                end 
                cost_at_sel(qsel==qsel_indices) = best_cost; 

                % Sub-step 2d+: Interpolate orientations that are not optimized 
                if find(qsel==qsel_indices)>1 
                    % mid_indices = qsel + ((-skipsample+1):1:-1); 
                    mid_indices = (qsel_indices(find(qsel==qsel_indices)-1)+1):(qsel-1); 
                    qs = orient_traj(:,mid_indices(1)-1); 
                    qt = orient_traj(:,mid_indices(end)+1); 
                    qdel = qt-qs; 
                    len_mid_indices = length(mid_indices); 
                    alpha = linspace(0,1,len_mid_indices); 
                    mid_orient_traj = repmat(qs,1,len_mid_indices) + repmat(alpha,4,1)...
                        .*repmat(qdel,1,len_mid_indices); 
                    % orient_traj(:,mid_indices) = mid_orient_traj...
                    %     ./repmat(sqrt(sum(mid_orient_traj.^2,1)),4,1); 
                    for j=1:length(mid_indices) 
                        new_q = mid_orient_traj(:,j)/norm(mid_orient_traj(:,j)); 
                        gravity_orientation_error = ([0;0;obj.earth_gravity] - C_q(new_q)*g_all(:,qsel)); 
                        err_inrpltd = gravity_orientation_error'*Q*gravity_orientation_error; 
                        new_q = orient_traj(:,mid_indices(j))/norm(orient_traj(:,mid_indices(j))); 
                        gravity_orientation_error = ([0;0;obj.earth_gravity] - C_q(new_q)*g_all(:,qsel)); 
                        err_prev = gravity_orientation_error'*Q*gravity_orientation_error; 
                        if err_inrpltd<err_prev 
                            orient_traj(:,mid_indices(j)) = mid_orient_traj(:,j); 
                        end 
                    end 
                end 

                % Sub-step 2d++: 
                obj.best_quaternion_orientation_trajectory = orient_traj./repmat(sqrt(sum(orient_traj.^2,1)),4,1); 
                try 
                    save('best_orientation_so_far.mat','orient_traj','-append'); 
                catch 
                    warning('Not saved! ') 
                end 

                % Sub-step 2e: Progres bar 
                percent_done = find(qsel==qsel_indices)*100/length(qsel_indices); 
                clc; 
                disp(['Progress: <', repmat('||',1,floor(percent_done/3 )), '> ', num2str(percent_done), ' % ']) 
                % 
                figure(1) 
                clf 
                plot(qsel_indices,cost_at_sel,'--') 
                hold on 
                tmp = cost_at_sel; 
                tmp(epsilon>cost_at_sel) = nan; 
                plot(qsel_indices,tmp,'o') 
                plot(qsel_indices,epsilon*ones(1,length(tmp))) 
                hold off 
                title(['GD result (sum = ',num2str(sum(cost_at_sel(~isnan(cost_at_sel)))),')']) 
                xlabel('selected indices for correction --> ') 
                ylabel('best cost --> ') 
                pause(0.01) 
            end 

            disp('Convert to euler and save') 
            obj.best_euler_orientation_trajectory = obj.get_euler_orientation_trajectory(); 
            orient_traj_eul = obj.best_euler_orientation_trajectory; 
            try 
                save('best_orientation_so_far.mat','orient_traj_eul','-append'); 
            catch 
                warning('Not saved! ') 
            end 
            
            %% Step 2: Compare 
            figure(2) 
            obj.show_comparison_of_acclerometer_plot(); 
            
            %% Final step: 
            disp('  ') 
            disp('<<<< All STEPS completed! >>>>') 
            if pause_dbug_fcn3(); keyboard; end; clc 
        end 
        function main_best_orientation_trajectory_to(varargin) % TrajOpt 

            obj = varargin{1}; 
            if nargin>1 
                skipsample = varargin{2}; 
            else 
                skipsample = 1e4; 
            end 


            %% Step 1: testingv 
            testf = 50; 
            usegyrodata = 1; 
            % theta = rand*pi; 
            % vec = randn(3,1); 
            % orient_quat = [cos(theta/2);sin(theta/2)*vec/norm(vec)]; 
            max_steps = 30; 

            % Initialization 
            theta = -2.3*pi/4; 
            vec = [0;0;1]; 
            default_dp_len = obj.get_delta_index; % size(obj.all_datapoints,2); 
            orient_quat = repmat([cos(theta/2);sin(theta/2)*vec/norm(vec)],1,default_dp_len); 
            
            %% Step 3: 
            
            %% Step 4: Create gravity and rotation inline function  
            g_all = obj.get_gravity_at_fraction_or_index(obj.start_index:obj.end_index); 
            C_q = @(q) quat2rotm(q'); 
            try 
                load('best_orientation_so_far.mat'); 
                [~] = orient_traj; 
            catch 
                try 
                    qi = obj.best_initial_orientation; 
                    qf = obj.best_final_orientation; 
                    qdiff = qf-qi; 
                    alpha = linspace(0,1,default_dp_len); 
                    orient_traj = repmat(qi,1,default_dp_len) + repmat(alpha,4,1)...
                        .*repmat(qdiff,1,default_dp_len); 
                    orient_traj = orient_traj./repmat(sqrt(sum(orient_traj.^2,1)),4,1); 
                catch 
                    % gains_now = obj.imu_device_obj.get_gains(); 
                    orient_traj = orient_quat; 
                end 
            end 

            %% Step 2: Optimize the orientation quaternion 
            number_of_directions = 10; 
            grad_bounds = diag([1e-0*ones(1,4)]); 
            Q = diag([1e0,1e0,1e0]); % weight on the norm of final state 
            length_of_orient_vector = length(grad_bounds); 
            accleration_factor = 0.1; 
            qsel_indices = obj.start_index:skipsample:obj.end_index; 
            for qsel=qsel_indices 
                for i=1:max_steps 
                    % Sub-step 2a: Choose gradients at uniformly random 
                    random_orient_grads = [zeros(length_of_orient_vector,1), rand(length_of_orient_vector, number_of_directions-1)]; 
    
                    % Sub-step 2b: Find new points along the random gradients 
                    new_orients = repmat(orient_traj(:,qsel),1,number_of_directions) + accleration_factor*random_orient_grads; 
    
                    % Sub-step 2c: Evaluate end gps point for all new states 
                    all_costs = inf(1,number_of_directions); 
                    for j=1:number_of_directions 
                        new_q = new_orients(:,j)/norm(new_orients(:,j)); 
                        gravity_orientation_error = ([0;0;obj.earth_gravity] - C_q(new_q)*g_all(:,qsel)); 
                        all_costs(1,j) = gravity_orientation_error'*Q*gravity_orientation_error; 
                    end 
    
                    % Sub-step 2d: Choose the best and set it as new gain 
                    [~,best_arg] = min(all_costs); 
                    orient_traj(:,qsel) = new_orients(:,best_arg); 
                end 

                % Sub-step 2d+: Interpolate orientations that are not optimized 
                if qsel>1 
                    mid_indices = qsel + ((-skipsample+1):1:-1); 
                    qs = orient_traj(:,mid_indices(1)-1); 
                    qt = orient_traj(:,mid_indices(end)+1); 
                    qdel = qt-qs; 
                    len_mid_indices = length(mid_indices); 
                    alpha = linspace(0,1,len_mid_indices); 
                    mid_orient_traj = repmat(qs,1,len_mid_indices) + repmat(alpha,4,1)...
                        .*repmat(qdel,1,len_mid_indices); 
                    orient_traj(:,mid_indices) = mid_orient_traj...
                        ./repmat(sqrt(sum(mid_orient_traj.^2,1)),4,1); 
                end 

                % Sub-step 2d++: 
                obj.best_quaternion_orientation_trajectory = orient_traj./repmat(sqrt(sum(orient_traj.^2,1)),4,1); 
                try 
                    save('best_orientation_so_far.mat','orient_traj','-append'); 
                catch 
                    warning('Not saved! ') 
                end 

                % Sub-step 2e: Progres bar 
                percent_done = qsel*100/default_dp_len; 
                clc; 
                disp(['Progress: <', repmat('||',1,floor(percent_done/3 )), '> ', num2str(percent_done), ' % ']) 
            end 

            disp('Convert to euler and save') 
            obj.best_euler_orientation_trajectory = obj.get_euler_orientation_trajectory(); 
            
            %% Step 2: Compare 
            disp('Effect of orientation on gravity: ') 
            % disp(C_q(obj.best_initial_orientation)*g_init) 
            
            %% Final step: 
            disp('  ') 
            disp('<<<< All STEPS completed! >>>>') 
            if pause_dbug_fcn3(); keyboard; end; clc 
        end 
        function main_best_gains(obj) 


            %% Step 1: testingv 
            testf = 50; 
            usegyrodata = 1; 
            % theta = rand*pi; 
            % vec = randn(3,1); 
            % orient_quat = [cos(theta/2);sin(theta/2)*vec/norm(vec)]; 
            max_steps = 30; 

            % Initialization 
            theta = -2.3*pi/4; 
            vec = [0;0;1]; 
            orient_quat = [cos(theta/2);sin(theta/2)*vec/norm(vec)]; 
            
            %% Step 3: Sort data into control singals 
            len_data = length(obj.datapoints(1,:)); 
            disp(['Length of dataset = ', num2str(len_data)]) 
            gyr = obj.datapoints(1:3,1:min(len_data,end))'; 
            acc = obj.datapoints(4:6,1:min(len_data,end))'; 
            
            %% Step 4: Create IMU object and load initial gain selection 
            obj.imu_device_obj = imu_device(obj.start_gps,orient_quat); 
            try 
                load('best_IMUgain_so_far.mat'); 
                [~] = gains_now; 
            catch 
                % gains_now = obj.imu_device_obj.get_gains(); 
                gains_now = obj.imu_device_obj.get_diag_gains(); 
            end 
            try 
                load('best_orientation_so_far.mat'); 
                [~] = orient_now; 
            catch 
                % gains_now = obj.imu_device_obj.get_gains(); 
                orient_now = orient_quat; 
            end 

            %% Step 2: Optimize the gains 
            number_of_directions = 50; 
            grad_bounds = diag([1e-7*ones(1,3),1e-7*ones(1,3)]); 
            Q = diag([1e14,1e14,1]); % weight on the norm of final state 
            length_of_gain_vector = length(grad_bounds); 
            accleration_factor = 0.1; 
            for i=1:max_steps 
                % Sub-step 2a: Choose gradients at uniformly random 
                random_gain_grads = [zeros(length_of_gain_vector,1), grad_bounds*rand(length_of_gain_vector, number_of_directions-1)]; 

                % Sub-step 2b: Find new points along the random gradients 
                new_gains = repmat(gains_now,1,number_of_directions) + accleration_factor*random_gain_grads; 

                % Sub-step 2c: Evaluate end gps point for all new states 
                all_costs = inf(1,number_of_directions); 
                for j=1:number_of_directions 
                    obj.imu_device_obj.reset_state(); 
                    % obj.imu_device_obj.set_gains(new_gains(:,j)); 
                    obj.imu_device_obj.set_diag_gains(new_gains(:,j)); 
                    obj.imu_device_obj.set_init_orient(orient_now/norm(orient_now)); 
                    obj.imu_device_obj.generate_traj_ode(acc,usegyrodata*gyr,obj.timepoints/testf); 
                    final_state = obj.imu_device_obj.get_current_state(); 
                    all_costs(1,j) = (final_state(1:3)-obj.end_gps')'*Q*(final_state(1:3)-obj.end_gps'); 
                end 

                % Sub-step 2d: Choose the best and set it as new gain 
                [~,best_arg] = min(all_costs); 
                gains_now = new_gains(:,best_arg); 
                obj.best_gain = gains_now; 
                save best_IMUgain_so_far gains_now 

                % Sub-step 2e: Progres bar 
                percent_done = i*100/max_steps; 
                clc; 
                disp(['Progress: <', repmat('||',1,floor(percent_done/3 )), '> ', num2str(percent_done), ' % ']) 
            end 
            
            %% Step 2: Render environment and IMU device best trajectory 
            figure(1) 
            obj.show_markers_geoplot(); 
            obj.imu_device_obj.generate_traj_ode(acc,usegyrodata*gyr,obj.timepoints/testf); 
            obj.imu_device_obj.reset_state(); 
            obj.imu_device_obj.set_diag_gains(obj.best_gain); 
            obj.imu_device_obj.set_init_orient(orient_now/norm(orient_now)); 
            obj.imu_device_obj.generate_traj_ode(acc,usegyrodata*gyr,obj.timepoints/testf); 
            hold on 
            obj.imu_device_obj.geoplot_traj(); 
            hold off 
            
            %% Step 5: Print 
            disp('Started at location: ') 
            disp(obj.imu_device_obj.traj_table(1,2:4)) 
            disp('Now at location: ') 
            disp(obj.imu_device_obj.traj_table(end,2:4)) 
            disp('True end at location: ') 
            disp(obj.end_gps) 
            disp('Started at orientation: ') 
            disp(obj.imu_device_obj.traj_table(1,5:8)) 
            disp('Now at orientation: ') 
            disp(obj.imu_device_obj.traj_table(end,5:8)) 
            
            %% Final step: 
            disp('  ') 
            disp('<<<< All STEPS completed! >>>>') 
            if pause_dbug_fcn3(); keyboard; end; clc 
        end 
        function main_best_gains_and_orientation(obj) 


            %% Step 1: testingv 
            testf = 50; 
            usegyrodata = 1; 
            % theta = rand*pi; 
            % vec = randn(3,1); 
            % orient_quat = [cos(theta/2);sin(theta/2)*vec/norm(vec)]; 
            max_steps = 3; 

            % Initialization 
            theta = -2.3*pi/4; 
            vec = [0;0;1]; 
            orient_quat = [cos(theta/2);sin(theta/2)*vec/norm(vec)]; 
            
            %% Step 3: Sort data into control singals 
            len_data = length(obj.datapoints(1,:)); 
            disp(['Length of dataset = ', num2str(len_data)]) 
            gyr = obj.datapoints(1:3,1:min(len_data,end))'; 
            acc = obj.datapoints(4:6,1:min(len_data,end))'; 
            
            %% Step 4: Create IMU object and load initial gain selection 
            obj.imu_device_obj = imu_device(obj.start_gps,orient_quat); 
            try 
                load('best_IMUgain_so_far.mat'); 
                [~] = gains_now; 
            catch 
                % gains_now = obj.imu_device_obj.get_gains(); 
                gains_now = obj.imu_device_obj.get_diag_gains(); 
            end 
            try 
                load('best_orientation_so_far.mat'); 
                [~] = orient_now; 
            catch 
                % gains_now = obj.imu_device_obj.get_gains(); 
                orient_now = orient_quat; 
            end 

            %% Step 2: Optimize the gains 
            number_of_directions = 50; 
            grad_bounds = diag([1e-7*ones(1,3),1e-7*ones(1,3)]); 
            Q = diag([1e14,1e14,1]); % weight on the norm of final state 
            length_of_gain_vector = length(grad_bounds); 
            accleration_factor = 0.1; 
            for i=1:max_steps 
                % Sub-step 2a: Choose gradients at uniformly random 
                random_gain_grads = [zeros(length_of_gain_vector,1), grad_bounds*rand(length_of_gain_vector, number_of_directions-1)]; 
                random_orient_grads = [zeros(4,1), rand(4, number_of_directions-1)]; 

                % Sub-step 2b: Find new points along the random gradients 
                new_gains = repmat(gains_now,1,number_of_directions) + accleration_factor*random_gain_grads; 
                new_orients = repmat(orient_now,1,number_of_directions) + accleration_factor*random_orient_grads; 

                % Sub-step 2c: Evaluate end gps point for all new states 
                all_costs = inf(1,number_of_directions); 
                for j=1:number_of_directions 
                    obj.imu_device_obj.reset_state(); 
                    % obj.imu_device_obj.set_gains(new_gains(:,j)); 
                    obj.imu_device_obj.set_diag_gains(new_gains(:,j)); 
                    obj.imu_device_obj.set_init_orient(new_orients(:,j)/norm(new_orients(:,j))); 
                    obj.imu_device_obj.generate_traj_ode(acc,usegyrodata*gyr,obj.timepoints/testf); 
                    final_state = obj.imu_device_obj.get_current_state(); 
                    all_costs(1,j) = (final_state(1:3)-obj.end_gps')'*Q*(final_state(1:3)-obj.end_gps'); 
                end 

                % Sub-step 2d: Choose the best and set it as new gain 
                [~,best_arg] = min(all_costs); 
                gains_now = new_gains(:,best_arg); 
                orient_now = new_orients(:,best_arg); 
                obj.best_gain = gains_now; 
                obj.best_initial_orientation = orient_now/norm(orient_now); 
                save best_IMUgain_so_far gains_now 
                save('best_orientation_so_far.mat','orient_now','-append'); 
                

                % Sub-step 2e: Progres bar 
                percent_done = i*100/max_steps; 
                clc; 
                disp(['Progress: <', repmat('||',1,floor(percent_done/3 )), '> ', num2str(percent_done), ' % ']) 
            end 
            
            %% Step 2: Render environment and IMU device best trajectory 
            figure(1) 
            obj.show_markers_geoplot(); 
            obj.imu_device_obj.generate_traj_ode(acc,usegyrodata*gyr,obj.timepoints/testf); 
            obj.imu_device_obj.reset_state(); 
            obj.imu_device_obj.set_diag_gains(obj.best_gain); 
            obj.imu_device_obj.set_init_orient(obj.best_initial_orientation); 
            obj.imu_device_obj.generate_traj_ode(acc,usegyrodata*gyr,obj.timepoints/testf); 
            hold on 
            obj.imu_device_obj.geoplot_traj(); 
            hold off 
            
            %% Step 5: Print 
            disp('Started at location: ') 
            disp(obj.imu_device_obj.traj_table(1,2:4)) 
            disp('Now at location: ') 
            disp(obj.imu_device_obj.traj_table(end,2:4)) 
            disp('True end at location: ') 
            disp(obj.end_gps) 
            disp('Started at orientation: ') 
            disp(obj.imu_device_obj.traj_table(1,5:8)) 
            disp('Now at orientation: ') 
            disp(obj.imu_device_obj.traj_table(end,5:8)) 
            
            %% Final step: 
            disp('  ') 
            disp('<<<< All STEPS completed! >>>>') 
            if pause_dbug_fcn3(); keyboard; end; clc 
        end 
        function main_best_gains_and_states(varargin) % GradDesc 


            obj = varargin{1}; 
            if nargin>1 
                skipsample = varargin{2}; 
            else 
                skipsample = 1e4/obj.downsampling; 
            end 
            if nargin>2 
                [lwr,upr] = varargin{2:end}; 
                qsel_indices = floor(linspace(lwr,upr,30)); 
            end 
            if nargin>3 
                [lwr,upr,spcd] = varargin{2:end}; 
                qsel_indices = floor(linspace(lwr,upr,spcd)); 
            end 


            %% Step 1: testingv 
            testf = 50; 
            usegyrodata = 1; 
            % theta = rand*pi; 
            % vec = randn(3,1); 
            % orient_quat = [cos(theta/2);sin(theta/2)*vec/norm(vec)]; 

            % Initialization 
            theta = -2.3*pi/4; 
            vec = [0;0;1]; 
            default_dp_len = obj.get_delta_index; % size(obj.all_datapoints,2); 
            orient_quat = repmat([cos(theta/2);sin(theta/2)*vec/norm(vec)],1,default_dp_len); 
            
            %% Step 3: Algorithm parameters 
            epsilon = 1e-2; 
            max_steps = 30000; 
            
            %% Step 4: Create gravity and rotation inline function  
            g_all = obj.get_gravity_at_fraction_or_index(obj.start_index:obj.end_index); 
            C_q = @(q) quat2rotm(q'); 
            try 
                load('best_orientation_so_far.mat'); 
                [~] = orient_traj; 
            catch 
                try 
                    qi = obj.best_initial_orientation; 
                    qf = obj.best_final_orientation; 
                    qdiff = qf-qi; 
                    alpha = linspace(0,1,default_dp_len); 
                    orient_traj = repmat(qi,1,default_dp_len) + repmat(alpha,4,1)...
                        .*repmat(qdiff,1,default_dp_len); 
                    orient_traj = orient_traj./repmat(sqrt(sum(orient_traj.^2,1)),4,1); 
                catch 
                    % gains_now = obj.imu_device_obj.get_gains(); 
                    orient_traj = orient_quat; 
                end 
            end 

            %% Step 2: Optimize the orientation quaternion 
            number_of_random_points = 10; 
            number_of_new_orientations = 20; 
            grad_bounds = diag([1e-0*ones(1,4)]); 
            Q = diag([1e0,1e0,1e0]); % weight on the norm of final state 
            length_of_orient_vector = length(grad_bounds); 
            accleration_factor = 0.1; 
            try % qsel_indices was input by user 
                [~] = qsel_indices; 
            catch 
                qsel_indices = obj.start_index:skipsample:obj.end_index; 
            end 
            cost_at_sel = nan(1,length(qsel_indices)); 
            for qsel=qsel_indices 
                for i=1:max_steps 
                    % Sub-step 2a: Choose gradients at uniformly random 
                    random_orient_grads = [zeros(length_of_orient_vector,1), ...
                        2*(0.5-rand(length_of_orient_vector, number_of_new_orientations-1))]; 
    
                    % Sub-step 2b: Find new points along the random
                    % gradients + random points 
                    new_orients = repmat(orient_traj(:,qsel),1,number_of_new_orientations) + accleration_factor*random_orient_grads; 
                    new_orients(:,number_of_new_orientations-number_of_random_points+1:end) ...
                        = 2*(0.5-rand(4,number_of_random_points)); 
    
                    % Sub-step 2c: Evaluate end gps point for all new states 
                    all_costs = inf(1,number_of_new_orientations); 
                    for j=1:number_of_new_orientations 
                        new_q = new_orients(:,j)/norm(new_orients(:,j)); 
                        gravity_orientation_error = (C_q(new_q)*g_all(:,qsel)-[0;0;obj.earth_gravity]); 
                        all_costs(1,j) = gravity_orientation_error'*Q*gravity_orientation_error; 
                    end 
    
                    % Sub-step 2d: Choose the best and set it as new gain 
                    [best_cost,best_arg] = min(all_costs); 
                    orient_traj(:,qsel) = new_orients(:,best_arg)/norm(new_orients(:,best_arg)); 

                    % Sub-step 2e: Breaking condition 
                    if best_cost<epsilon 
                        break 
                    end 
                end 
                cost_at_sel(qsel==qsel_indices) = best_cost; 

                % Sub-step 2d+: Interpolate orientations that are not optimized 
                if find(qsel==qsel_indices)>1 
                    % mid_indices = qsel + ((-skipsample+1):1:-1); 
                    mid_indices = (qsel_indices(find(qsel==qsel_indices)-1)+1):(qsel-1); 
                    qs = orient_traj(:,mid_indices(1)-1); 
                    qt = orient_traj(:,mid_indices(end)+1); 
                    qdel = qt-qs; 
                    len_mid_indices = length(mid_indices); 
                    alpha = linspace(0,1,len_mid_indices); 
                    mid_orient_traj = repmat(qs,1,len_mid_indices) + repmat(alpha,4,1)...
                        .*repmat(qdel,1,len_mid_indices); 
                    % orient_traj(:,mid_indices) = mid_orient_traj...
                    %     ./repmat(sqrt(sum(mid_orient_traj.^2,1)),4,1); 
                    for j=1:length(mid_indices) 
                        new_q = mid_orient_traj(:,j)/norm(mid_orient_traj(:,j)); 
                        gravity_orientation_error = ([0;0;obj.earth_gravity] - C_q(new_q)*g_all(:,qsel)); 
                        err_inrpltd = gravity_orientation_error'*Q*gravity_orientation_error; 
                        new_q = orient_traj(:,mid_indices(j))/norm(orient_traj(:,mid_indices(j))); 
                        gravity_orientation_error = ([0;0;obj.earth_gravity] - C_q(new_q)*g_all(:,qsel)); 
                        err_prev = gravity_orientation_error'*Q*gravity_orientation_error; 
                        if err_inrpltd<err_prev 
                            orient_traj(:,mid_indices(j)) = mid_orient_traj(:,j); 
                        end 
                    end 
                end 

                % Sub-step 2d++: 
                %                 obj.best_quaternion_orientation_trajectory = orient_traj./repmat(sqrt(sum(orient_traj.^2,1)),4,1); 
                %                 try 
                %                     save('best_orientation_so_far.mat','orient_traj','-append'); 
                %                 catch 
                %                     warning('Not saved! ') 
                %                 end 

                % Sub-step 2e: Progres bar 
                percent_done = find(qsel==qsel_indices)*100/length(qsel_indices); 
                clc; 
                disp(['Progress: <', repmat('||',1,floor(percent_done/3 )), '> ', num2str(percent_done), ' % ']) 
                % 
                figure(1) 
                clf 
                plot(qsel_indices,cost_at_sel,'--') 
                hold on 
                tmp = cost_at_sel; 
                tmp(epsilon>cost_at_sel) = nan; 
                plot(qsel_indices,tmp,'o') 
                plot(qsel_indices,epsilon*ones(1,length(tmp))) 
                hold off 
                title(['GD result (sum = ',num2str(sum(cost_at_sel(~isnan(cost_at_sel)))),')']) 
                xlabel('selected indices for correction --> ') 
                ylabel('best cost --> ') 
                pause(0.01) 
            end 

            disp('Convert to euler and save') 
            %             obj.best_euler_orientation_trajectory = obj.get_euler_orientation_trajectory(); 
            %             orient_traj_eul = obj.best_euler_orientation_trajectory; 
            %             try 
            %                 save('best_orientation_so_far.mat','orient_traj_eul','-append'); 
            %             catch 
            %                 warning('Not saved! ') 
            %             end 
            
            %% Step 2: Compare 
            figure(2) 
            obj.show_comparison_of_acclerometer_plot(); 
            
            %% Final step: 
            disp('  ') 
            disp('<<<< All STEPS completed! >>>>') 
            if pause_dbug_fcn3(); keyboard; end; clc 
        end 
    end 
    methods % All show functions 
        %% Rendering: show_ 
        function show_markers_geoplot(obj) 
            geoplot(obj.marker_data.lat(obj.selected_marker_indices), ...
                obj.marker_data.lon(obj.selected_marker_indices), 'g-*')
            text(obj.marker_data.lat(obj.selected_marker_indices), ...
                obj.marker_data.lon(obj.selected_marker_indices), ...
                num2str(obj.marker_data.name(obj.selected_marker_indices))) 
            title('Marker locations on map') 
        end 
        function show_all_markers_geoplot(obj) 
            geoplot(obj.marker_data.lat, obj.marker_data.lon, 'g-*') 
            title('Marker locations on map') 
        end 
        function show_all_markers_and_ref_geoplot(obj) 
            geoplot(obj.marker_data.lat, obj.marker_data.lon, 'g-*') 
            hold on 
            geoplot(obj.ref_data.lat,obj.ref_data.lon,'-.') 
            hold off 
            for i=1:size(obj.marker_data,1) 
                text(obj.marker_data.lat(i),obj.marker_data.lon(i),obj.marker_data.name(i))
            end 
            title('Marker locations on map') 
        end 
        function show_all_markers_elevation(obj) 
            plot(obj.marker_data.hgt) 
            grid on 
            xlabel('Marker number') 
            ylabel('Elevation (in meters)') 
            title('Marker elevations') 
        end 
        function show_imu_plot(varargin) 
            obj = varargin{1}; 
            sel_data = 4:6; 
            skip_points = 10; 
            total_points_to_print = obj.end_index/skip_points; 
            if nargin==2 
                [obj, sel_data] = varargin{:}; 
            elseif nargin==4 
                [obj, sel_data, skip_points, total_points_to_print] = varargin{:}; 
            end 
            print_total = min(skip_points*total_points_to_print,length(obj.all_timepoints)); 
            plot(obj.all_timepoints(obj.start_index:skip_points:print_total)', ...
                obj.all_datapoints(sel_data,obj.start_index:skip_points:print_total)') 
            grid on 
            xlabel('time') 
            ylabel('Readings') 
            legend(obj.imudata_names{sel_data}) 
            title('IMU data') 
            disp(' <<<< Plot settings >>>> ') 
            disp([' --> Skipping points = ', num2str(skip_points)]) 
            disp([' --> Last point index = ', num2str(print_total)]) 
        end 
        function show_imu_static_plot(varargin) 
            obj = varargin{1}; 
            sel_data = 4:6; 
            skip_points = 10; 
            if nargin==2 
                [obj, sel_data] = varargin{:}; 
            elseif nargin>=3 
                [obj, sel_data, skip_points] = varargin{:}; 
            end 
