        function show_imu_variance_linear_velocity_magnitude_plot(varargin) 
            disp('Action: cumsum( acc_magntude - special_mean )*delT ') 
            obj = varargin{1}; 
            sel_data = 4:6; 
            skip_points = 10; 
            total_points_to_print = obj.end_index/skip_points; 
            if nargin==3 
                [obj, skip_points, total_points_to_print] = varargin{:}; 
            end 
            print_total = min(skip_points*total_points_to_print,length(obj.all_timepoints)); 
            acc_dp = obj.all_datapoints(sel_data,obj.start_index:skip_points:print_total); 
            k_acc = obj.get_accelerometer_gain(); 
            acc_norm = k_acc*sqrt(sum(acc_dp.*acc_dp,1)); 
            special_mean = obj.earth_gravity; % BAD 
            % special_mean = obj.earth_gravity-0.005; % Adjusted 
            % special_mean = mean(acc_norm); % Zero to zero 
            % special_mean = mean(acc_norm(16e3:17e3)); % Mean in motion 
            % special_mean = mean(acc_norm(16e4:17e4)); % Mean at the end 
            vel_var_norm = cumsum(obj.downsampling*(acc_norm-special_mean)/obj.sampling_frequency); 
            plot(obj.all_timepoints(obj.start_index:skip_points:print_total)', vel_var_norm') 
            grid on 
            xlabel('time') 
            ylabel('Velocity (mean/gravity removed)') 
            title(['Magnitude of velocity variation (integrated acceleration variance)']) 
            disp(' <<<< Plot settings >>>> ') 
            disp([' --> Skipping points = ', num2str(skip_points)]) 
            disp([' --> Last point index = ', num2str(print_total)]) 
            disp([' --> Value of `special_mean` = ', num2str(special_mean)]) 
        end 
        function show_imu_variance_linear_displacement_magnitude_plot(varargin) 
            disp('Action: cumsum( acc_magntude - special_mean )*delT ') 
            obj = varargin{1}; 
            sel_data = 4:6; 
            skip_points = 10; 
            total_points_to_print = obj.end_index/skip_points; 
            if nargin==3 
                [obj, skip_points, total_points_to_print] = varargin{:}; 
            end 
            print_total = min(skip_points*total_points_to_print,length(obj.all_timepoints)); 
            acc_dp = obj.all_datapoints(sel_data,obj.start_index:skip_points:print_total); 
            k_acc = obj.get_accelerometer_gain(); 
            acc_norm = k_acc*sqrt(sum(acc_dp.*acc_dp,1)); 
            special_mean = obj.earth_gravity; % BAD 
            % special_mean = obj.earth_gravity-0.005; % Adjusted 
            % special_mean = mean(acc_norm); % Zero to zero 
            % special_mean = mean(acc_norm(16e3:17e3)); % Mean in motion 
            % special_mean = mean(acc_norm(16e4:17e4)); % Mean at the end 
