    methods (Access=private) % Useless as of now 
        function main_best_init_orient_gains_and_wrong_biases_gd(obj) 

            clf 
            %% Step 1: testingv 
            testf = 50; 
            usegyrodata = 1; 
            % theta = rand*pi; 
            % vec = randn(3,1); 
            % orient_quat = [cos(theta/2);sin(theta/2)*vec/norm(vec)]; 
            max_steps = 180; 

            % Initialization 
            theta = -2.3*pi/4; 
            vec = [0;0;1]; 
            orient_quat = [cos(theta/2);sin(theta/2)*vec/norm(vec)]; 
            
            %% Step 3: Sort data into control singals 
            len_data = length(obj.datapoints(1,:)); 
            disp(['Length of dataset = ', num2str(len_data)]) 
            gyr = obj.datapoints(1:3,1:min(len_data,end))'; 
            acc = obj.datapoints(4:6,1:min(len_data,end))'; 

            % Load 
            try 
                load('best_agb.mat') 
                [~] = agb_now; 
            catch 
                % init of tuning parameters 
                agb_now = [180;1;1;1;0;0;0]; % angle, gains, bias 
            end 
            
            %% Step 4: Optimize the angle, gains and bias 
            number_of_directions = 50; 
            grad_bounds = 5e-2*diag([2e0,1e-5*ones(1,3),1e0*[1e-5,1e-5],1e7*1e-6]); 
            Q = diag([1e6,1e6,1e-8]); % weight on the norm of final state 
            length_of_gain_vector = length(grad_bounds); 
            accleration_factor = 0.1; 
            % for dynamics 
            indices = obj.start_index:obj.end_index; 
            g_all = obj.get_gravity_at_fraction_or_index(indices); 
            C_q = @(q) quat2rotm(q'); 
            noindices = length(indices); 
            G_matrix = @(p) diag([(180/pi)/(obj.north_radius_of_earth + p(3)), ...
                -(180/pi)/((obj.east_radius_of_earth + p(3))*cosd(p(1))), 1]); % Lat Lon Up 
            % 
            for i=1:max_steps 
                % Sub-step 2a: Choose gradients at uniformly random 
                random_gain_grads = [zeros(length_of_gain_vector,1), 2*grad_bounds*(0.5-rand(length_of_gain_vector, number_of_directions-1))]; 

                % Sub-step 2b: Find new points along the random gradients 
                new_agb = repmat(agb_now,1,number_of_directions) + accleration_factor*random_gain_grads; 

                % Sub-step 2c: Evaluate end gps point for all new states 
                all_costs = inf(1,number_of_directions); 
                for j=1:number_of_directions 
                    z_angle = new_agb(1,j); 
                    acc_gain_mat = diag(new_agb(2:4,1))+diag(10*[0.01,0.01,0.01]); 
                    % acc_gain_mat = diag(new_agb(2:4,j)); 
                    warning('gain has been manually fixed! ') 
                    acc_bias = new_agb(5:7,j); 
                    v_dot = zeros(3,noindices); 
                    v = zeros(3,noindices); 
                    p_gen = zeros(3,noindices); 
                    p_gen(:,1) = obj.start_gps'; 
                    for ix=1:noindices 
                        indx = indices(ix); 
                        new_q = obj.best_quaternion_orientation_trajectory(:,indx); 
                        v_dot(:,ix) = rotz(z_angle)*C_q(new_q)*acc_gain_mat*g_all(:,ix) - [0;0;obj.earth_gravity] + acc_bias; 
                        if ix>1 
                            dT = obj.downsampling*(indices(ix)-indices(ix-1))/obj.sampling_frequency; 
                            v(:,ix) = v(:,ix-1) + dT*v_dot(:,ix-1); 
                            p_gen(:,ix) = p_gen(:,ix-1) + dT*G_matrix(p_gen(:,ix-1))*v(:,ix-1); 
                        end 
                    end 
                    final_state = p_gen(:,end); 
                    straightning_cost = 0*norm([p_gen(1,ceil(noindices/2)),p_gen(2,ceil(noindices/2))] - ...
                        [mean([obj.start_gps(1),obj.end_gps(1)]),mean([obj.start_gps(2),obj.end_gps(2)])]); 
                    all_costs(1,j) = (final_state(1:3)-obj.end_gps')'*Q*(final_state(1:3)-obj.end_gps') ...
                        + straightning_cost; 
                    % start-1 < for testing > 
                    figure(1) 
                    geoplot(p_gen(1,1)',p_gen(2,1)','x'); 
                    hold on 
                    geoplot(p_gen(1,:)',p_gen(2,:)'); 
                    geoplot(obj.end_gps(1),obj.end_gps(2),'o'); 
                    hold off 
                    title(['i = ', num2str(i), ' | elevation error = ', ...
                        num2str(obj.end_gps(3)-p_gen(3,end))]) 
                    figure(2) 
                    clf; stem(all_costs); hold on; plot(min(all_costs)*ones(1,number_of_directions), '--'); hold off 
                    % disp(all_costs(1,1:j)) 
                    % disp(straightning_cost) 
                    disp((final_state(1:3)-obj.end_gps').*diag(Q).*(final_state(1:3)-obj.end_gps')) 
                    % end-1 < for testing >
                end 

                % Sub-step 2d: Choose the best and set it as new gain 
                [~,best_arg] = min(all_costs); 
                agb_now = new_agb(:,best_arg); 
                % see plots 
                figure(1) % <-- testing 
                z_angle = agb_now(1); 
                % acc_gain_mat = diag(agb_now(2:4)); 
                acc_bias = agb_now(5:7); 
                v_dot = zeros(3,noindices); 
                v = zeros(3,noindices); 
                p_gen = zeros(3,noindices); 
                p_gen(:,1) = obj.start_gps'; 
                for ix=1:noindices 
                    indx = indices(ix); 
                    new_q = obj.best_quaternion_orientation_trajectory(:,indx); 
                    v_dot(:,ix) = rotz(z_angle)*C_q(new_q)*acc_gain_mat*g_all(:,ix) - [0;0;obj.earth_gravity] + acc_bias; 
                    if ix>1 
                        dT = obj.downsampling*(indices(ix)-indices(ix-1))/obj.sampling_frequency; 
                        v(:,ix) = v(:,ix-1) + dT*v_dot(:,ix-1); 
                        p_gen(:,ix) = p_gen(:,ix-1) + dT*G_matrix(p_gen(:,ix-1))*v(:,ix-1); 
                    end 
                end 
                final_state = p_gen(:,end); 
                disp((final_state(1:3)-obj.end_gps').*diag(Q).*(final_state(1:3)-obj.end_gps')) 
                geoplot(p_gen(1,1)',p_gen(2,1)','x'); 
                hold on 
                geoplot(p_gen(1,:)',p_gen(2,:)'); 
                geoplot(obj.end_gps(1),obj.end_gps(2),'o'); 
                hold off 
                title(['iter = ', num2str(i), ' | elevation error = ', ...
                    num2str(obj.end_gps(3)-p_gen(3,end))]) 
                pause(0.1) 
%                 disp('don`t save untill fixed!' )
%                 keyboard 
%                 error('stop i said! ') 
                % save 
                save 'best_agb.mat' agb_now 

                % Sub-step 2e: Progres bar 
                percent_done = i*100/max_steps; 
                clc; 
                disp(['Progress: <', repmat('||',1,floor(percent_done/3 )), '> ', num2str(percent_done), ' % ']) 
            end 
            
            %% Step 2: Render environment and IMU device best trajectory 
            figure(1) 
            obj.show_markers_geoplot(); 
            obj.imu_device_obj.generate_traj_ode(acc,usegyrodata*gyr,obj.timepoints/testf); 
            obj.imu_device_obj.reset_state(); 
            obj.imu_device_obj.set_diag_gains(obj.best_gain); 
            obj.imu_device_obj.set_init_orient(orient_now/norm(orient_now)); 
            obj.imu_device_obj.generate_traj_ode(acc,usegyrodata*gyr,obj.timepoints/testf); 
            hold on 
            obj.imu_device_obj.geoplot_traj(); 
            hold off 
            
            %% Step 5: Print 
            disp('Started at location: ') 
            disp(obj.imu_device_obj.traj_table(1,2:4)) 
            disp('Now at location: ') 
            disp(obj.imu_device_obj.traj_table(end,2:4)) 
            disp('True end at location: ') 
            disp(obj.end_gps) 
            disp('Started at orientation: ') 
            disp(obj.imu_device_obj.traj_table(1,5:8)) 
            disp('Now at orientation: ') 
            disp(obj.imu_device_obj.traj_table(end,5:8)) 
            
            %% Final step: 
            disp('  ') 
            disp('<<<< All STEPS completed! >>>>') 
            if pause_dbug_fcn3(); keyboard; end; clc 
        end         
        function mavg_dp = get_moving_average_of_all_datapoints(varargin) 
            obj = varargin{1}; 
            if nargin>1 
                obj.moving_average_window = varargin{2}; 
            end 
            if nargin>2 
                obj.moving_average_coeffs = varargin{3}; 
            end  
            adp_len = length(obj.all_timepoints); 
            indx_shift_for_mavg = -(obj.moving_average_window-1):(obj.moving_average_window-1); 
            to_time = tic; 
            for i=1:length(obj.all_timepoints) 
                % window selection 
                if i<obj.moving_average_window 
                    indx = 1:(obj.moving_average_window-1+i); 
                    coeffs = obj.moving_average_coeffs(indx); 
                elseif i>adp_len-obj.moving_average_window 
                    indx = (adp_len-obj.moving_average_window+1):adp_len; 
                    coeffs = obj.moving_average_coeffs(indx-indx(1)+(i+obj.moving_average_window -100)); 
                else 
                    indx = indx_shift_for_mavg + i; 
                    coeffs = obj.moving_average_coeffs; 
                end 
                % averaging now 
                obj.all_datapoints(:,i) = obj.raw_datapoints(:,indx)*coeffs; 
            end 
            mavg_dp = obj.all_datapoints; 
            toc(to_time) 
        end 
        function x_dot = integrator_dynamics(obj,t,x) 
            x_dot = x + obj.all_datapoints(:,obj.integrator_input_index); 
        end 
        function [q_dot,q,v_dot,v,p_gen,odo_gen,acc_ef] = get_full_ekf_dynamical_trajectory_manifold_unknown_sampling(varargin) 
            obj = varargin{1}; 
            agb_now = varargin{2};  % <-- angle, gains, and biases 
            if nargin>2 % epsilon 
                epsilon = varargin{3}; 
            else 
                epsilon = 1; 
            end 
            if nargin>3 % indices 
                indices = varargin{4}; 
            else 
                indices = obj.start_index:obj.end_index; 
            end 
            if nargin>4 % g and w as input 
                g_all = varargin{5}; 
                w_all = varargin{6}; 
                f = varargin{7}; 
                g = varargin{8}; 
                C_nb = varargin{9}; 
            else 
                g_all = obj.get_gravity_at_fraction_or_index(indices); 
                w_all = diag(obj.best_gain(4:end))*obj.all_datapoints(1:3,indices); 
            end 
            % 
            % odo_gain = 1; %agb_now(1); 
            % acc_gain_mat = diag(agb_now(2:4)); 
            acc_bias = agb_now(5:7); 
            % gyro_gain_mat = diag(agb_now(8:10)); 
            gyro_bias = agb_now(11:13); 
            params = [agb_now([2:4,8:10]);agb_now(21)*obj.downsampling/10]; 
            % q0 = obj.best_initial_orientation + agb_now(14:17); 
            q0 = rotm2quat(rotx(obj.start_gps(2))*roty(obj.start_gps(1))*quat2rotm(obj.best_initial_orientation'))'...
                 + agb_now(14:17); 
            v0 = agb_now(18:20); 
            dT = agb_now(21)*(indices(2)-indices(1))*obj.downsampling/10; 
            % 
            noindices = length(indices); 
            % 
            q_dot = zeros(4,noindices); 
            q = zeros(4,noindices); 
            v_dot = zeros(3,noindices); 
            v = zeros(3,noindices); 
            p_gen = zeros(3,noindices); 
            odo_gen = zeros(1,noindices); 
            acc_ef = zeros(3,noindices); 
            q(:,1) = q0; % <-- normalized later 
            v(:,1) = v0; % 
            p_gen(:,1) = obj.start_gps'; 
            % 
            for ix=2:noindices 
                indx = indices(ix-1); 
                old_q = obj.best_quaternion_orientation_trajectory(:,indx); 
                new_q = epsilon*old_q + (1-epsilon)*q(:,ix-1); 
                new_q = new_q/norm(new_q); 
                % dT = obj.downsampling*(indices(ix)-indices(ix-1))/obj.sampling_frequency; 
                t = dT*(ix-2); 
                % 
                x = [odo_gen(:,ix-1);p_gen(:,ix-1);new_q;v(:,ix-1);acc_bias;gyro_bias]; 
                u = [g_all(:,ix-1);w_all(:,ix-1)]; 
                x = f(x) + g(t,x,u,params); 
                odo_gen(:,ix) = x(1); p_gen(:,ix) = x(2:4); q(:,ix) = x(5:8); v(:,ix) = x(9:11); 
                % 
                q_dot(:,ix) = (q(:,ix) - q(:,ix-1))/dT; 
                v_dot(:,ix) = (v(:,ix) - v(:,ix-1))/dT; 
                acc_ef(:,ix) = transpose(C_nb(dT*(ix-1),p_gen(:,ix),q(:,ix),v(:,ix)))...
                    *[0;0;obj.earth_gravity]; 
            end 
            % odo_gen = odo_gain*dT*cumsum(sqrt(sum(v.*v,1))); 
        end 
    end 
end 

